    out = [_wl(f"c{i:03d}", s, d, 640, 480, 640, 480, BILINEAR) for i, (s, d) in enumerate(_PAIRS)]
    out += [_wl(f"s{i:03d}", *cfg) for i, cfg in enumerate(_SCALES)]
    return out


