    rgb2yuv: k.Rgb2Yuv = undefined,

    // generic pipeline
    chr_src_hsub: u5 = 0,
    chr_src_vsub: u5 = 0,
    chr_dst_hsub: u5 = 0,
    chr_dst_vsub: u5 = 0,
    chr_src_w: i32 = 0,
    chr_src_h: i32 = 0,
    chr_dst_w: i32 = 0,
    chr_dst_h: i32 = 0,
    out_mode: OutMode = .planar,
    need_alpha: bool = false,
    has_chroma_in: bool = true,
    lum_range: k.Range = .none,
    chr_range: k.Range = .none,
    hlum: filt.Filter = undefined,
    hchr: filt.Filter = undefined,
    vlum: filt.Filter = undefined,
    vchr: filt.Filter = undefined,
    lum_need: []bool = &.{},
    chr_need: []bool = &.{},
    lum_buf: []i16 = &.{},
    alp_buf: []i16 = &.{},
    u_buf: []i16 = &.{},
    v_buf: []i16 = &.{},
    tmp16a: []i16 = &.{},
    tmp16b: []i16 = &.{},
    tmp16c: []i16 = &.{},
    tmp8a: []u8 = &.{},
    tmp8b: []u8 = &.{},
    lum_stride: usize = 0,
    chr_stride: usize = 0,
};

fn freeSlice(comptime T: type, s: []T) void {
    if (s.len != 0) alloc.free(s);
}

fn destroyCtx(c: *Ctx) void {
    if (c.kind == .generic) {
        c.hlum.deinit();
        c.hchr.deinit();
        c.vlum.deinit();
        c.vchr.deinit();
    }
    freeSlice(bool, c.lum_need);
    freeSlice(bool, c.chr_need);
    freeSlice(i16, c.lum_buf);
    freeSlice(i16, c.alp_buf);
    freeSlice(i16, c.u_buf);
    freeSlice(i16, c.v_buf);
    freeSlice(i16, c.tmp16a);
    freeSlice(i16, c.tmp16b);
    freeSlice(i16, c.tmp16c);
    freeSlice(u8, c.tmp8a);
    freeSlice(u8, c.tmp8b);
    alloc.destroy(c);
}

fn initGeneric(c: *Ctx, algo: filt.Algo) !void {
    const sw = c.src_w;
    const sh = c.src_h;
    const dw = c.dst_w;
    const dh = c.dst_h;
    var full = false;
    c.chr_src_hsub = chrH(c.src_fmt);
    c.chr_src_vsub = chrV(c.src_fmt);
    c.chr_dst_hsub = chrH(c.dst_fmt);
    c.chr_dst_vsub = chrV(c.dst_fmt);
    if (isRGB(c.dst_fmt)) {
        if (dw & 1 != 0) full = true;
        if (c.chr_src_hsub == 0 and c.chr_src_vsub == 0) full = true;
        if (!full) c.chr_dst_hsub = 1;
        c.out_mode = if (full) .rgb_full else .rgb_half;
    } else {
        c.out_mode = .planar;
    }
    if (isRGB(c.src_fmt) and (dw >> c.chr_dst_hsub) <= (sw >> 1)) c.chr_src_hsub = 1;
    c.chr_src_w = ceilShr(sw, c.chr_src_hsub);
    c.chr_src_h = ceilShr(sh, c.chr_src_vsub);
    c.chr_dst_w = ceilShr(dw, c.chr_dst_hsub);
    c.chr_dst_h = ceilShr(dh, c.chr_dst_vsub);
    c.need_alpha = hasAlpha(c.src_fmt) and hasAlpha(c.dst_fmt);
    c.has_chroma_in = c.src_fmt != .gray8 and c.dst_fmt != .gray8;

    // range handling: gray is full range, everything else (YUV) limited; RGB forced 0
    const src_range: u1 = if (c.src_fmt == .gray8) 1 else 0;
    const dst_range: u1 = if (c.dst_fmt == .gray8) 1 else 0;
    if (src_range != dst_range and !isRGB(c.dst_fmt)) {
        c.lum_range = if (src_range == 1) .from_jpeg else .to_jpeg;
        c.chr_range = c.lum_range;
    }

    const lumXInc: i32 = @intCast(((@as(i64, sw) << 16) + (dw >> 1)) Fdiv dw);
    _ = lumXInc;
}

