// Scaler filter construction — a port of FFmpeg's initFilter() for the
// point / bilinear / bicubic kernels with default parameters.

const std = @import("std");
const alloc = std.heap.c_allocator;

pub const Algo = enum { point, bilinear, bicubic };

pub const Filter = struct {
    size: usize,
    n: usize,
    pos: []i32,
    coef: []i16,

    pub fn deinit(self: *Filter) void {
        alloc.free(self.pos);
        alloc.free(self.coef);
    }
};

fn absI64(v: i64) i64 {
    return if (v < 0) -v else v;
}

fn avLog2(v: u32) u32 {
    const x = v | 1;
    return 31 - @as(u32, @clz(x));
}

fn roundedDiv(a: i64, b: i64) i64 {
    return if (a >= 0) @divTrunc(a + (b >> 1), b) else @divTrunc(a - (b >> 1), b);
}

pub fn init(xInc: i32, srcW: i32, dstW: i32, one: i64, algo: Algo, srcPos: i32, dstPos: i32) !Filter {
    const dw: usize = @intCast(dstW);
    const ratio: u32 = @intCast(@divTrunc(srcW, dstW));
    const lg = @min(avLog2(ratio), 8);
    const fone: i64 = @as(i64, 1) << @intCast(54 - lg);
    const xinc: i64 = xInc;

    var pos = try alloc.alloc(i32, dw + 3);
    errdefer alloc.free(pos);
    var filterSize: usize = 0;
    var filter: []i64 = undefined;

    if (absI64(xinc - 0x10000) < 10 and srcPos == dstPos) {
        filterSize = 1;
        filter = try alloc.alloc(i64, dw);
        for (0..dw) |i| {
            filter[i] = fone;
            pos[i] = @intCast(i);
        }
    } else if (algo == .point) {
        filterSize = 1;
        filter = try alloc.alloc(i64, dw);
        var xDstInSrc: i64 = ((@as(i64, dstPos) * xinc) >> 8) - ((@as(i64, srcPos) * 0x8000) >> 7);
        for (0..dw) |i| {
            const xx = (xDstInSrc + (1 << 15)) >> 16;
            pos[i] = @intCast(xx);
            filter[i] = fone;
            xDstInSrc += xinc;
        }
    } else {
        const sizeFactor: i64 = if (algo == .bilinear) 2 else 4;
        var fs: i64 = if (xinc <= 1 << 16) 1 + sizeFactor else 1 + @divTrunc(sizeFactor * srcW + dstW - 1, dstW);
        fs = @min(fs, srcW - 2);
        fs = @max(fs, 1);
        filterSize = @intCast(fs);
        filter = try alloc.alloc(i64, dw * filterSize);
        var xDstInSrc: i64 = ((@as(i64, dstPos) * xinc) >> 7) - ((@as(i64, srcPos) * 0x10000) >> 7);
        for (0..dw) |i| {
            var xx: i64 = @divTrunc(xDstInSrc - (fs - 2) * (1 << 16), 1 << 17);
            pos[i] = @intCast(xx);
            for (0..filterSize) |j| {
                var d: i64 = absI64(xx * (1 << 17) - xDstInSrc) << 13;
                if (xinc > 1 << 16) d = @divTrunc(d * dstW, srcW);
                var coeff: i64 = 0;
                if (algo == .bicubic) {
                    const B: i64 = 0;
                    const C: i64 = @intFromFloat(@as(f64, 0.6) * @as(f64, 1 << 24));
                    if (d >= @as(i64, 1) << 31) {
                        coeff = 0;
                    } else {
                        const dd = (d * d) >> 30;
                        const ddd = (dd * d) >> 30;
                        if (d < @as(i64, 1) << 30) {
                            coeff = (12 * (1 << 24) - 9 * B - 6 * C) * ddd +
                                (-18 * (1 << 24) + 12 * B + 6 * C) * dd +
                                (6 * (1 << 24) - 2 * B) * (1 << 30);
                        } else {
                            coeff = (-B - 6 * C) * ddd +
                                (6 * B + 30 * C) * dd +
                                (-12 * B - 48 * C) * d +
                                (8 * B + 24 * C) * (1 << 30);
                        }
                    }
                    coeff = @divTrunc(coeff, @divTrunc(@as(i64, 1) << 54, fone));
                } else {
                    coeff = (1 << 30) - d;
                    if (coeff < 0) coeff = 0;
                    coeff *= fone >> 30;
                }
                filter[i * filterSize + j] = coeff;
                xx += 1;
            }
            xDstInSrc += 2 * xinc;
        }
    }
    defer alloc.free(filter);

    // filter2 == filter (no src/dst vectors)
    const f2s = filterSize;
    const filter2 = filter;
    const cutoffLimit: f64 = 0.002 * @as(f64, @floatFromInt(fone));

    var minFilterSize: usize = 0;
    var ii: isize = @as(isize, @intCast(dw)) - 1;
    while (ii >= 0) : (ii -= 1) {
        const i: usize = @intCast(ii);
        var min: usize = f2s;
        var cutOff: i64 = 0;
        for (0..f2s) |_| {
            cutOff += absI64(filter2[i * f2s]);
            if (@as(f64, @floatFromInt(cutOff)) > cutoffLimit) break;
            if (i < dw - 1 and pos[i] >= pos[i + 1]) break;
            var kk: usize = 1;
            while (kk < f2s) : (kk += 1) filter2[i * f2s + kk - 1] = filter2[i * f2s + kk];
            filter2[i * f2s + kk - 1] = 0;
            pos[i] += 1;
        }
        cutOff = 0;
        var j: usize = f2s - 1;
        while (j > 0) : (j -= 1) {
            cutOff += absI64(filter2[i * f2s + j]);
            if (@as(f64, @floatFromInt(cutOff)) > cutoffLimit) break;
            min -= 1;
        }
        if (min > minFilterSize) minFilterSize = min;
    }
    const fsz = minFilterSize;
    var f = try alloc.alloc(i64, dw * fsz);
    defer alloc.free(f);
    for (0..dw) |i| {
        for (0..fsz) |j| {
            f[i * fsz + j] = if (j >= f2s) 0 else filter2[i * f2s + j];
        }
    }
    const sW: i32 = srcW;
    const fszi: i32 = @intCast(fsz);
    for (0..dw) |i| {
        if (pos[i] < 0) {
            var j: usize = 1;
            while (j < fsz) : (j += 1) {
                const left: usize = @intCast(@max(@as(i32, @intCast(j)) + pos[i], 0));
                f[i * fsz + left] += f[i * fsz + j];
                f[i * fsz + j] = 0;
            }
            pos[i] = 0;
        }
        if (pos[i] + fszi > sW) {
            const shift: i32 = pos[i] + @min(fszi - sW, 0);
            var acc: i64 = 0;
            var jj: i32 = fszi - 1;
            while (jj >= 0) : (jj -= 1) {
                const j: usize = @intCast(jj);
                if (pos[i] + jj >= sW) {
                    acc += f[i * fsz + j];
                    f[i * fsz + j] = 0;
                }
            }
            jj = fszi - 1;
            while (jj >= 0) : (jj -= 1) {
                const j: usize = @intCast(jj);
                if (jj < shift) {
                    f[i * fsz + j] = 0;
                } else {
                    f[i * fsz + j] = f[i * fsz + @as(usize, @intCast(jj - shift))];
                }
            }
            pos[i] -= shift;
            f[i * fsz + @as(usize, @intCast(sW - 1 - pos[i]))] += acc;
        }
    }
    var coef = try alloc.alloc(i16, fsz * (dw + 3));
    @memset(coef, 0);
    for (0..dw) |i| {
        var err: i64 = 0;
        var sum: i64 = 0;
        for (0..fsz) |j| sum += f[i * fsz + j];
        sum = @divTrunc(sum + @divTrunc(one, 2), one);
        if (sum == 0) sum = 1;
        for (0..fsz) |j| {
            const v = f[i * fsz + j] + err;
            const intV = roundedDiv(v, sum);
            coef[i * fsz + j] = @intCast(intV);
            err = v - intV * sum;
        }
    }
    pos[dw] = pos[dw - 1];
    pos[dw + 1] = pos[dw - 1];
    pos[dw + 2] = pos[dw - 1];
    return .{ .size = fsz, .n = dw, .pos = pos, .coef = coef };
}

