// libswscale_candidate — image scaling and pixel-format conversion.
//
// The arithmetic mirrors FFmpeg's scalar swscale (filter construction, 15-bit
// horizontal intermediates, 12-bit vertical filters, table-driven YUV->RGB),
// so output tracks the reference bit-for-bit.  Hot loops live in kernels.zig
// and use @Vector for portable SIMD.

const std = @import("std");
const filt = @import("filter.zig");
const k = @import("kernels.zig");

const alloc = std.heap.c_allocator;

pub const Fmt = enum(c_int) {
    yuv420p = 0,
    yuv422p = 1,
    yuv444p = 2,
    nv12 = 3,
    nv21 = 4,
    rgb24 = 5,
    bgr24 = 6,
    rgba = 7,
    bgra = 8,
    gray8 = 9,
};

fn isRGB(f: Fmt) bool {
    return switch (f) {
        .rgb24, .bgr24, .rgba, .bgra => true,
        else => false,
    };
}
fn isPlanarYUV(f: Fmt) bool {
    return f == .yuv420p or f == .yuv422p or f == .yuv444p;
}
fn isNV(f: Fmt) bool {
    return f == .nv12 or f == .nv21;
}
fn hasAlpha(f: Fmt) bool {
    return f == .rgba or f == .bgra;
}
fn chrH(f: Fmt) u5 {
    return switch (f) {
        .yuv420p, .yuv422p, .nv12, .nv21 => 1,
        else => 0,
    };
}
fn chrV(f: Fmt) u5 {
    return switch (f) {
        .yuv420p, .nv12, .nv21 => 1,
        else => 0,
    };
}
fn ceilShr(v: i32, s: u5) i32 {
    return -((-v) >> s);
}
fn rgbLayout(f: Fmt) k.RgbLayout {
    return switch (f) {
        .rgb24 => .{ .bpp = 3, .r = 0, .g = 1, .b = 2, .a = 0 },
        .bgr24 => .{ .bpp = 3, .r = 2, .g = 1, .b = 0, .a = 0 },
        .rgba => .{ .bpp = 4, .r = 0, .g = 1, .b = 2, .a = 3 },
        .bgra => .{ .bpp = 4, .r = 2, .g = 1, .b = 0, .a = 3 },
        else => unreachable,
    };
}

const Kind = enum { yuv2rgb_tab, planar_to_nv, nv_to_planar, bgr24_to_yv12, rgb_shuffle, gray_to_rgb, copy, generic };

pub const OutMode = enum { planar, rgb_half, rgb_full };

pub const Ctx = struct {
    src_w: i32,
    src_h: i32,
    dst_w: i32,
    dst_h: i32,
    src_fmt: Fmt,
    dst_fmt: Fmt,
    kind: Kind,

    yt: k.YuvTables = undefined,
    c2y: k.Rgb2Yuv = undefined,

    // generic pipeline
    chr_src_hsub: u5 = 0,
    chr_src_vsub: u5 = 0,
    chr_dst_hsub: u5 = 0,
    chr_dst_vsub: u5 = 0,
    chr_src_w: i32 = 0,
    chr_src_h: i32 = 0,
    chr_dst_w: i32 = 0,
    chr_dst_h: i32 = 0,
    out_mode: OutMode = .planar,
    need_alpha: bool = false,
    has_chroma_in: bool = true,
    lum_range: k.Range = .none,
    chr_range: k.Range = .none,
    hlum: filt.Filter = undefined,
    hchr: filt.Filter = undefined,
    vlum: filt.Filter = undefined,
    vchr: filt.Filter = undefined,
    lum_need: []bool = &.{},
    chr_need: []bool = &.{},
    lum_buf: []i16 = &.{},
    alp_buf: []i16 = &.{},
    u_buf: []i16 = &.{},
    v_buf: []i16 = &.{},
    tmp16a: []i16 = &.{},
    tmp16b: []i16 = &.{},
    tmp8a: []u8 = &.{},
    tmp8b: []u8 = &.{},
    lum_stride: usize = 0,
    chr_stride: usize = 0,
    filters_ok: bool = false,
};

fn freeSlice(comptime T: type, s: []T) void {
    if (s.len != 0) alloc.free(s);
}

fn destroyCtx(c: *Ctx) void {
    if (c.filters_ok) {
        c.hlum.deinit();
        c.hchr.deinit();
        c.vlum.deinit();
        c.vchr.deinit();
    }
    freeSlice(bool, c.lum_need);
    freeSlice(bool, c.chr_need);
    freeSlice(i16, c.lum_buf);
    freeSlice(i16, c.alp_buf);
    freeSlice(i16, c.u_buf);
    freeSlice(i16, c.v_buf);
    freeSlice(i16, c.tmp16a);
    freeSlice(i16, c.tmp16b);
    freeSlice(u8, c.tmp8a);
    freeSlice(u8, c.tmp8b);
    alloc.destroy(c);
}

fn initGeneric(c: *Ctx, algo: filt.Algo) !void {
    const sw = c.src_w;
    const sh = c.src_h;
    const dw = c.dst_w;
    const dh = c.dst_h;
    var full = false;
    c.chr_src_hsub = chrH(c.src_fmt);
    c.chr_src_vsub = chrV(c.src_fmt);
    c.chr_dst_hsub = chrH(c.dst_fmt);
    c.chr_dst_vsub = chrV(c.dst_fmt);
    if (isRGB(c.dst_fmt)) {
        if (dw & 1 != 0) full = true;
        if (c.chr_src_hsub == 0 and c.chr_src_vsub == 0) full = true;
        if (!full) c.chr_dst_hsub = 1;
        c.out_mode = if (full) .rgb_full else .rgb_half;
    } else {
        c.out_mode = .planar;
    }
    if (isRGB(c.src_fmt) and (dw >> c.chr_dst_hsub) <= (sw >> 1)) c.chr_src_hsub = 1;
    c.chr_src_w = ceilShr(sw, c.chr_src_hsub);
    c.chr_src_h = ceilShr(sh, c.chr_src_vsub);
    c.chr_dst_w = ceilShr(dw, c.chr_dst_hsub);
    c.chr_dst_h = ceilShr(dh, c.chr_dst_vsub);
    c.need_alpha = hasAlpha(c.src_fmt) and hasAlpha(c.dst_fmt);
    c.has_chroma_in = c.src_fmt != .gray8 and c.dst_fmt != .gray8;

    // gray is full range, YUV limited; RGB never range-converts
    const src_range: u1 = if (c.src_fmt == .gray8) 1 else 0;
    const dst_range: u1 = if (c.dst_fmt == .gray8) 1 else 0;
    if (src_range != dst_range and !isRGB(c.dst_fmt)) {
        c.lum_range = if (src_range == 1) .from_jpeg else .to_jpeg;
        c.chr_range = c.lum_range;
    }

    const lumXInc: i32 = @intCast(@divTrunc((@as(i64, sw) << 16) + (dw >> 1), dw));
    const lumYInc: i32 = @intCast(@divTrunc((@as(i64, sh) << 16) + (dh >> 1), dh));
    const chrXInc: i32 = @intCast(@divTrunc((@as(i64, c.chr_src_w) << 16) + (c.chr_dst_w >> 1), c.chr_dst_w));
    const chrYInc: i32 = @intCast(@divTrunc((@as(i64, c.chr_src_h) << 16) + (c.chr_dst_h >> 1), c.chr_dst_h));

    c.hlum = try filt.init(lumXInc, sw, dw, 1 << 14, algo, 128, 128);
    c.hchr = try filt.init(chrXInc, c.chr_src_w, c.chr_dst_w, 1 << 14, algo, 128, 128);
    c.vlum = try filt.init(lumYInc, sh, dh, 1 << 12, algo, 128, 128);
    c.vchr = try filt.init(chrYInc, c.chr_src_h, c.chr_dst_h, 1 << 12, algo, 128, 128);
    c.filters_ok = true;

    // Which source rows are actually referenced by the vertical filters.
    c.lum_need = try alloc.alloc(bool, @intCast(sh));
    @memset(c.lum_need, false);
    c.chr_need = try alloc.alloc(bool, @intCast(c.chr_src_h));
    @memset(c.chr_need, false);
    const vdh: usize = @intCast(dh);
    for (0..vdh) |y| {
        const p: usize = @intCast(c.vlum.pos[y]);
        for (0..c.vlum.size) |j| c.lum_need[p + j] = true;
    }
    const cdh: usize = @intCast(c.chr_dst_h);
    for (0..cdh) |y| {
        const p: usize = @intCast(c.vchr.pos[y]);
        for (0..c.vchr.size) |j| c.chr_need[p + j] = true;
    }

    const pad = 64;
    c.lum_stride = (@as(usize, @intCast(dw)) + pad) & ~@as(usize, 15);
    c.chr_stride = (@as(usize, @intCast(c.chr_dst_w)) + pad) & ~@as(usize, 15);
    c.lum_buf = try alloc.alloc(i16, c.lum_stride * @as(usize, @intCast(sh)));
    if (c.need_alpha) c.alp_buf = try alloc.alloc(i16, c.lum_stride * @as(usize, @intCast(sh)));
    if (c.has_chroma_in) {
        c.u_buf = try alloc.alloc(i16, c.chr_stride * @as(usize, @intCast(c.chr_src_h)));
        c.v_buf = try alloc.alloc(i16, c.chr_stride * @as(usize, @intCast(c.chr_src_h)));
    }
    const tw: usize = @as(usize, @intCast(sw)) + 64;
    c.tmp16a = try alloc.alloc(i16, tw);
    c.tmp16b = try alloc.alloc(i16, tw);
    @memset(c.tmp16a, 0);
    @memset(c.tmp16b, 0);
    c.tmp8a = try alloc.alloc(u8, tw);
    c.tmp8b = try alloc.alloc(u8, tw);
    @memset(c.tmp8a, 0);
    @memset(c.tmp8b, 0);
}

fn createImpl(sw: c_int, sh: c_int, sf: c_int, dw: c_int, dh: c_int, df: c_int, algo_i: c_int) !*Ctx {
    if (sw <= 0 or sh <= 0 or dw <= 0 or dh <= 0) return error.Invalid;
    if (sf < 0 or sf > 9 or df < 0 or df > 9 or algo_i < 0 or algo_i > 2) return error.Invalid;
    const c = try alloc.create(Ctx);
    c.* = .{
        .src_w = sw,
        .src_h = sh,
        .dst_w = dw,
        .dst_h = dh,
        .src_fmt = @enumFromInt(sf),
        .dst_fmt = @enumFromInt(df),
        .kind = .generic,
    };
    errdefer destroyCtx(c);
    c.yt = k.YuvTables.init();
    c.c2y = k.Rgb2Yuv.init();
    const algo: filt.Algo = switch (algo_i) {
        0 => .point,
        1 => .bilinear,
        else => .bicubic,
    };
    const s = c.src_fmt;
    const d = c.dst_fmt;
    const unscaled = sw == dw and sh == dh;
    if (unscaled) {
        const src_range = s == .gray8;
        const dst_range = d == .gray8;
        if (src_range == dst_range or isRGB(d)) {
            var kind: ?Kind = null;
            if (s == .yuv420p and isNV(d)) kind = .planar_to_nv;
            if (d == .yuv420p and isNV(s)) kind = .nv_to_planar;
            if ((s == .yuv420p or s == .yuv422p) and isRGB(d) and (dh & 1) == 0) kind = .yuv2rgb_tab;
            if (s == .bgr24 and d == .yuv420p and (dw & 1) == 0) kind = .bgr24_to_yv12;
            if (isRGB(s) and isRGB(d) and s != d) kind = .rgb_shuffle;
            if (s == .gray8 and isRGB(d)) kind = .gray_to_rgb;
            if (s == d or (isPlanarYUV(s) and d == .gray8) or (isPlanarYUV(d) and s == .gray8) or
                (isPlanarYUV(s) and isPlanarYUV(d) and chrH(s) == chrH(d) and chrV(s) == chrV(d)))
                kind = .copy;
            if (kind) |kk| {
                c.kind = kk;
                return c;
            }
        }
    }
    c.kind = .generic;
    try initGeneric(c, algo);
    return c;
}

export fn swscale_create(src_w: c_int, src_h: c_int, src_fmt: c_int, dst_w: c_int, dst_h: c_int, dst_fmt: c_int, algo: c_int) ?*anyopaque {
    const c = createImpl(src_w, src_h, src_fmt, dst_w, dst_h, dst_fmt, algo) catch return null;
    return @ptrCast(c);
}

export fn swscale_destroy(handle: ?*anyopaque) void {
    if (handle) |p| destroyCtx(@ptrCast(@alignCast(p)));
}

inline fn rowPtr(base: [*]const u8, stride: c_int, y: usize) [*]const u8 {
    return base + @as(usize, @intCast(stride)) * y;
}
inline fn rowPtrMut(base: [*]u8, stride: c_int, y: usize) [*]u8 {
    return base + @as(usize, @intCast(stride)) * y;
}

export fn swscale_process(
    handle: ?*anyopaque,
    src_data: [*]const ?[*]const u8,
    src_stride: [*]const c_int,
    dst_data: [*]const ?[*]u8,
    dst_stride: [*]const c_int,
) c_int {
    const c: *Ctx = @ptrCast(@alignCast(handle orelse return -1));
    switch (c.kind) {
        .generic => processGeneric(c, src_data, src_stride, dst_data, dst_stride),
        .yuv2rgb_tab => processYuv2RgbTab(c, src_data, src_stride, dst_data, dst_stride),
        .planar_to_nv => {
            const w: usize = @intCast(c.src_w);
            const h: usize = @intCast(c.src_h);
            copyPlane(src_data[0].?, src_stride[0], dst_data[0].?, dst_stride[0], w, h);
            const cw = (w + 1) / 2;
            const ch = (h + 1) / 2;
            const swap = c.dst_fmt == .nv21;
            for (0..ch) |y| {
                const u = rowPtr(src_data[1].?, src_stride[1], y);
                const v = rowPtr(src_data[2].?, src_stride[2], y);
                const o = rowPtrMut(dst_data[1].?, dst_stride[1], y);
                if (swap) k.interleave(o, v, u, cw) else k.interleave(o, u, v, cw);
            }
        },
        .nv_to_planar => {
            const w: usize = @intCast(c.src_w);
            const h: usize = @intCast(c.src_h);
            copyPlane(src_data[0].?, src_stride[0], dst_data[0].?, dst_stride[0], w, h);
            const cw = (w + 1) / 2;
            const ch = (h + 1) / 2;
            const swap = c.src_fmt == .nv21;
            for (0..ch) |y| {
                const s = rowPtr(src_data[1].?, src_stride[1], y);
                const u = rowPtrMut(dst_data[1].?, dst_stride[1], y);
                const v = rowPtrMut(dst_data[2].?, dst_stride[2], y);
                if (swap) k.deinterleave(v, u, s, cw) else k.deinterleave(u, v, s, cw);
            }
        },
        .bgr24_to_yv12 => {
            const w: usize = @intCast(c.src_w);
            const h: usize = @intCast(c.src_h);
            var y: usize = 0;
            while (y + 1 < h + 1 and y < h) : (y += 2) {
                const s1 = rowPtr(src_data[0].?, src_stride[0], y);
                const s2 = rowPtr(src_data[0].?, src_stride[0], y + 1);
                k.bgr24ToYv12Rows(&c.c2y, s1, s2, rowPtrMut(dst_data[0].?, dst_stride[0], y), rowPtrMut(dst_data[0].?, dst_stride[0], y + 1), rowPtrMut(dst_data[1].?, dst_stride[1], y / 2), rowPtrMut(dst_data[2].?, dst_stride[2], y / 2), w / 2);
            }
        },
        .rgb_shuffle => {
            const w: usize = @intCast(c.src_w);
            const h: usize = @intCast(c.src_h);
            const sl = rgbLayout(c.src_fmt);
            const dl = rgbLayout(c.dst_fmt);
            for (0..h) |y| {
                k.rgbShuffle(rowPtrMut(dst_data[0].?, dst_stride[0], y), dl, rowPtr(src_data[0].?, src_stride[0], y), sl, w);
            }
        },
        .gray_to_rgb => {
            const w: usize = @intCast(c.src_w);
            const h: usize = @intCast(c.src_h);
            const dl = rgbLayout(c.dst_fmt);
            for (0..h) |y| {
                k.grayToRgb(rowPtrMut(dst_data[0].?, dst_stride[0], y), dl, rowPtr(src_data[0].?, src_stride[0], y), w);
            }
        },
        .copy => processCopy(c, src_data, src_stride, dst_data, dst_stride),
    }
    return 0;
}

fn copyPlane(src: [*]const u8, ss: c_int, dst: [*]u8, ds: c_int, w: usize, h: usize) void {
    for (0..h) |y| {
        @memcpy(rowPtrMut(dst, ds, y)[0..w], rowPtr(src, ss, y)[0..w]);
    }
}

fn processCopy(c: *Ctx, src: [*]const ?[*]const u8, ss: [*]const c_int, dst: [*]const ?[*]u8, ds: [*]const c_int) void {
    const w: usize = @intCast(c.src_w);
    const h: usize = @intCast(c.src_h);
    const s = c.src_fmt;
    const d = c.dst_fmt;
    if (isRGB(s)) {
        copyPlane(src[0].?, ss[0], dst[0].?, ds[0], w * rgbLayout(s).bpp, h);
        return;
    }
    if (isNV(s)) {
        copyPlane(src[0].?, ss[0], dst[0].?, ds[0], w, h);
        copyPlane(src[1].?, ss[1], dst[1].?, ds[1], ((w + 1) / 2) * 2, (h + 1) / 2);
        return;
    }
    copyPlane(src[0].?, ss[0], dst[0].?, ds[0], w, h);
    if (d == .gray8) return;
    const cw: usize = @intCast(ceilShr(c.src_w, chrH(d)));
    const ch: usize = @intCast(ceilShr(c.src_h, chrV(d)));
    if (s == .gray8) {
        for (1..3) |p| {
            for (0..ch) |y| @memset(rowPtrMut(dst[p].?, ds[p], y)[0..cw], 128);
        }
        return;
    }
    copyPlane(src[1].?, ss[1], dst[1].?, ds[1], cw, ch);
    copyPlane(src[2].?, ss[2], dst[2].?, ds[2], cw, ch);
}

fn processYuv2RgbTab(c: *Ctx, src: [*]const ?[*]const u8, ss: [*]const c_int, dst: [*]const ?[*]u8, ds: [*]const c_int) void {
    const w: usize = @intCast(c.src_w);
    const h: usize = @intCast(c.src_h);
    const is422 = c.src_fmt == .yuv422p;
    const dl = rgbLayout(c.dst_fmt);
    var y: usize = 0;
    while (y < h) : (y += 2) {
        const cy0 = if (is422) y else y >> 1;
        const cy1 = if (is422) y + 1 else y >> 1;
        k.yuv2rgbTabRow(&c.yt, rowPtrMut(dst[0].?, ds[0], y), dl, rowPtr(src[0].?, ss[0], y), rowPtr(src[1].?, ss[1], cy0), rowPtr(src[2].?, ss[2], cy0), w);
        if (y + 1 < h)
            k.yuv2rgbTabRow(&c.yt, rowPtrMut(dst[0].?, ds[0], y + 1), dl, rowPtr(src[0].?, ss[0], y + 1), rowPtr(src[1].?, ss[1], cy1), rowPtr(src[2].?, ss[2], cy1), w);
    }
}

fn processGeneric(c: *Ctx, src: [*]const ?[*]const u8, ss: [*]const c_int, dst: [*]const ?[*]u8, ds: [*]const c_int) void {
    const sw: usize = @intCast(c.src_w);
    const sh: usize = @intCast(c.src_h);
    const dw: usize = @intCast(c.dst_w);
    const dh: usize = @intCast(c.dst_h);
    const s = c.src_fmt;

    // ---- horizontal pass: luma (+alpha) ----
    for (0..sh) |y| {
        if (!c.lum_need[y]) continue;
        const out = c.lum_buf[y * c.lum_stride ..][0..dw];
        const row = rowPtr(src[0].?, ss[0], y);
        if (isRGB(s)) {
            const l = rgbLayout(s);
            k.rgbToY(&c.c2y, c.tmp16a.ptr, row, l, sw);
            k.hscale16(out.ptr, dw, c.tmp16a.ptr, &c.hlum);
            if (c.need_alpha) {
                k.rgbaToA(c.tmp16b.ptr, row, l, sw);
                k.hscale16(c.alp_buf[y * c.lum_stride ..].ptr, dw, c.tmp16b.ptr, &c.hlum);
            }
        } else {
            k.hscale8(out.ptr, dw, row, &c.hlum);
        }
        k.lumRange(c.lum_range, out.ptr, dw);
    }
    // ---- horizontal pass: chroma ----
    if (c.has_chroma_in) {
        const csh: usize = @intCast(c.chr_src_h);
        const cdw: usize = @intCast(c.chr_dst_w);
        const csw: usize = @intCast(c.chr_src_w);
        for (0..csh) |y| {
            if (!c.chr_need[y]) continue;
            const uo = c.u_buf[y * c.chr_stride ..].ptr;
            const vo = c.v_buf[y * c.chr_stride ..].ptr;
            if (isRGB(s)) {
                const row = rowPtr(src[0].?, ss[0], y);
                const l = rgbLayout(s);
                if (c.chr_src_hsub == 1) {
                    k.rgbToUVHalf(&c.c2y, c.tmp16a.ptr, c.tmp16b.ptr, row, l, csw);
                } else {
                    k.rgbToUV(&c.c2y, c.tmp16a.ptr, c.tmp16b.ptr, row, l, csw);
                }
                k.hscale16(uo, cdw, c.tmp16a.ptr, &c.hchr);
                k.hscale16(vo, cdw, c.tmp16b.ptr, &c.hchr);
            } else if (isNV(s)) {
                const row = rowPtr(src[1].?, ss[1], y);
                if (s == .nv12) k.deinterleave(c.tmp8a.ptr, c.tmp8b.ptr, row, csw) else k.deinterleave(c.tmp8b.ptr, c.tmp8a.ptr, row, csw);
                k.hscale8(uo, cdw, c.tmp8a.ptr, &c.hchr);
                k.hscale8(vo, cdw, c.tmp8b.ptr, &c.hchr);
            } else {
                k.hscale8(uo, cdw, rowPtr(src[1].?, ss[1], y), &c.hchr);
                k.hscale8(vo, cdw, rowPtr(src[2].?, ss[2], y), &c.hchr);
            }
            k.chrRange(c.chr_range, uo, vo, cdw);
        }
    }

    // ---- vertical pass + output ----
    var lumLines: [64][*]const i16 = undefined;
    var uLines: [64][*]const i16 = undefined;
    var vLines: [64][*]const i16 = undefined;
    var aLines: [64][*]const i16 = undefined;
    const d = c.dst_fmt;
    for (0..dh) |y| {
        const lp: usize = @intCast(c.vlum.pos[y]);
        const lsz = c.vlum.size;
        for (0..lsz) |j| {
            lumLines[j] = c.lum_buf[(lp + j) * c.lum_stride ..].ptr;
            if (c.need_alpha) aLines[j] = c.alp_buf[(lp + j) * c.lum_stride ..].ptr;
        }
        const lcoef = c.vlum.coef[y * lsz ..][0..lsz];
        switch (c.out_mode) {
            .planar => {
                k.vPlanar(rowPtrMut(dst[0].?, ds[0], y), dw, lumLines[0..lsz], lcoef);
                if (d == .gray8) continue;
                const mask = (@as(usize, 1) << c.chr_dst_vsub) - 1;
                if (y & mask != 0) continue;
                const cy = y >> c.chr_dst_vsub;
                const cdw: usize = @intCast(c.chr_dst_w);
                if (!c.has_chroma_in) {
                    if (isNV(d)) {
                        @memset(rowPtrMut(dst[1].?, ds[1], cy)[0 .. cdw * 2], 128);
                    } else {
                        @memset(rowPtrMut(dst[1].?, ds[1], cy)[0..cdw], 128);
                        @memset(rowPtrMut(dst[2].?, ds[2], cy)[0..cdw], 128);
                    }
                    continue;
                }
                const cp: usize = @intCast(c.vchr.pos[cy]);
                const csz = c.vchr.size;
                for (0..csz) |j| {
                    uLines[j] = c.u_buf[(cp + j) * c.chr_stride ..].ptr;
                    vLines[j] = c.v_buf[(cp + j) * c.chr_stride ..].ptr;
                }
                const ccoef = c.vchr.coef[cy * csz ..][0..csz];
                if (isNV(d)) {
                    const o = rowPtrMut(dst[1].?, ds[1], cy);
                    if (d == .nv12) k.vInterleaved(o, cdw, uLines[0..csz], vLines[0..csz], ccoef) else k.vInterleaved(o, cdw, vLines[0..csz], uLines[0..csz], ccoef);
                } else {
                    k.vPlanar(rowPtrMut(dst[1].?, ds[1], cy), cdw, uLines[0..csz], ccoef);
                    k.vPlanar(rowPtrMut(dst[2].?, ds[2], cy), cdw, vLines[0..csz], ccoef);
                }
            },
            .rgb_half, .rgb_full => {
                const cy = y;
                const cp: usize = @intCast(c.vchr.pos[cy]);
                const csz = c.vchr.size;
                for (0..csz) |j| {
                    uLines[j] = c.u_buf[(cp + j) * c.chr_stride ..].ptr;
                    vLines[j] = c.v_buf[(cp + j) * c.chr_stride ..].ptr;
                }
                const ccoef = c.vchr.coef[cy * csz ..][0..csz];
                const job = k.PackedJob{
                    .dst = rowPtrMut(dst[0].?, ds[0], y),
                    .w = dw,
                    .layout = rgbLayout(d),
                    .lum = lumLines[0..lsz],
                    .lcoef = lcoef,
                    .u = uLines[0..csz],
                    .v = vLines[0..csz],
                    .ccoef = ccoef,
                    .alpha = if (c.need_alpha) aLines[0..lsz] else null,
                };
                if (c.out_mode == .rgb_full) k.packedFull(&c.yt, &job) else k.packedHalf(&c.yt, &job);
            },
        }
    }
}

