// Per-row conversion kernels.  Scalar reference forms; SIMD fast paths are
// layered on top in simd.zig and dispatched from here.

const std = @import("std");
const filt = @import("filter.zig");
const simd = @import("simd.zig");

pub const RgbLayout = struct {
    bpp: usize,
    r: usize,
    g: usize,
    b: usize,
    a: usize,
};

pub const Range = enum { none, to_jpeg, from_jpeg };

inline fn clip8(v: i32) u8 {
    return @intCast(std.math.clamp(v, 0, 255));
}

fn roundToInt16(f: i64) i32 {
    const r = (f + (1 << 15)) >> 16;
    if (r < -0x7FFF) return -0x8000;
    if (r > 0x7FFF) return 0x7FFF;
    return @intCast(r);
}

// ---------------------------------------------------------------- tables

pub const YuvTables = struct {
    ytab: [2048]u8,
    offR: [256]i32,
    offGU: [256]i32,
    offGV: [256]i32,
    offB: [256]i32,
    // full-chroma arithmetic coefficients
    y_off: i32,
    y_coeff: i32,
    v2r: i32,
    v2g: i32,
    u2g: i32,
    u2b: i32,

    pub fn init() YuvTables {
        var t: YuvTables = undefined;
        var crv: i64 = 104597;
        var cbu: i64 = 132201;
        var cgu: i64 = -25675;
        var cgv: i64 = -53279;
        var cy: i64 = 1 << 16;
        var oy: i64 = 0;
        cy = @divTrunc(cy * 255, 219);
        oy = 16 << 16;
        const contrast: i64 = 1 << 16;
        const sat: i64 = 1 << 16;
        cy = (cy * contrast) >> 16;
        crv = (crv * contrast * sat) >> 32;
        cbu = (cbu * contrast * sat) >> 32;
        cgu = (cgu * contrast * sat) >> 32;
        cgv = (cgv * contrast * sat) >> 32;
        t.y_coeff = roundToInt16(cy * (1 << 13));
        t.y_off = roundToInt16(oy * (1 << 9));
        t.v2r = roundToInt16(crv * (1 << 13));
        t.v2g = roundToInt16(cgv * (1 << 13));
        t.u2g = roundToInt16(cgu * (1 << 13));
        t.u2b = roundToInt16(cbu * (1 << 13));
        crv = @divTrunc(crv * (1 << 16) + 0x8000, @max(cy, 1));
        cbu = @divTrunc(cbu * (1 << 16) + 0x8000, @max(cy, 1));
        cgu = @divTrunc(cgu * (1 << 16) + 0x8000, @max(cy, 1));
        cgv = @divTrunc(cgv * (1 << 16) + 0x8000, @max(cy, 1));
        var yb: i64 = -(384 << 16) - 512 * cy - oy;
        for (0..2048) |i| {
            t.ytab[i] = @intCast(std.math.clamp((yb + 0x8000) >> 16, 0, 255));
            yb += cy;
        }
        const yoffs: i64 = 326 + 512;
        for (0..256) |i| {
            const v: i64 = @intCast(i);
            t.offR[i] = @intCast(yoffs - (crv >> 9) + ((v * crv) >> 16));
            t.offGU[i] = @intCast(yoffs - (cgu >> 9) + ((v * cgu) >> 16));
            t.offGV[i] = @intCast(-(cgv >> 9) + ((v * cgv) >> 16));
            t.offB[i] = @intCast(yoffs - (cbu >> 9) + ((v * cbu) >> 16));
        }
        return t;
    }

    inline fn look(t: *const YuvTables, idx: i32) u8 {
        return t.ytab[@intCast(std.math.clamp(idx, 0, 2047))];
    }
};

pub const Rgb2Yuv = struct {
    ry: i32,
    gy: i32,
    by: i32,
    ru: i32,
    gu: i32,
    bu: i32,
    rv: i32,
    gv: i32,
    bv: i32,

    fn cf(comptime x: f64, comptime range: f64) i32 {
        const v: f64 = x * range / 255.0 * 32768.0 + 0.5;
        return @intFromFloat(v);
    }

    pub fn init() Rgb2Yuv {
        return .{
            .by = cf(0.114, 219),
            .bv = -cf(0.081, 224),
            .bu = cf(0.500, 224),
            .gy = cf(0.587, 219),
            .gv = -cf(0.419, 224),
            .gu = -cf(0.331, 224),
            .ry = cf(0.299, 219),
            .rv = cf(0.500, 224),
            .ru = -cf(0.169, 224),
        };
    }
};

// ---------------------------------------------------------------- unscaled

pub fn interleave(o: [*]u8, a: [*]const u8, b: [*]const u8, n: usize) void {
    for (0..n) |i| {
        o[2 * i] = a[i];
        o[2 * i + 1] = b[i];
    }
}

pub fn deinterleave(a: [*]u8, b: [*]u8, s: [*]const u8, n: usize) void {
    for (0..n) |i| {
        a[i] = s[2 * i];
        b[i] = s[2 * i + 1];
    }
}

pub fn bgr24ToYv12Rows(t: *const Rgb2Yuv, s1: [*]const u8, s2: [*]const u8, y1: [*]u8, y2: [*]u8, u: [*]u8, v: [*]u8, cw: usize) void {
    const ry: u32 = @bitCast(t.ry);
    const gy: u32 = @bitCast(t.gy);
    const by: u32 = @bitCast(t.by);
    const ru: u32 = @bitCast(t.ru);
    const gu: u32 = @bitCast(t.gu);
    const bu: u32 = @bitCast(t.bu);
    const rv: u32 = @bitCast(t.rv);
    const gv: u32 = @bitCast(t.gv);
    const bv: u32 = @bitCast(t.bv);
    for (0..cw) |i| {
        const b11: u32 = s1[6 * i + 0];
        const g11: u32 = s1[6 * i + 1];
        const r11: u32 = s1[6 * i + 2];
        const b12: u32 = s1[6 * i + 3];
        const g12: u32 = s1[6 * i + 4];
        const r12: u32 = s1[6 * i + 5];
        const b21: u32 = s2[6 * i + 0];
        const g21: u32 = s2[6 * i + 1];
        const r21: u32 = s2[6 * i + 2];
        const b22: u32 = s2[6 * i + 3];
        const g22: u32 = s2[6 * i + 4];
        const r22: u32 = s2[6 * i + 5];
        y1[2 * i + 0] = @truncate(((ry *% r11 +% gy *% g11 +% by *% b11) >> 15) +% 16);
        y1[2 * i + 1] = @truncate(((ry *% r12 +% gy *% g12 +% by *% b12) >> 15) +% 16);
        y2[2 * i + 0] = @truncate(((ry *% r21 +% gy *% g21 +% by *% b21) >> 15) +% 16);
        y2[2 * i + 1] = @truncate(((ry *% r22 +% gy *% g22 +% by *% b22) >> 15) +% 16);
        const bx = (b11 + b12 + b21 + b22) >> 2;
        const gx = (g11 + g12 + g21 + g22) >> 2;
        const rx = (r11 + r12 + r21 + r22) >> 2;
        u[i] = @truncate(((ru *% rx +% gu *% gx +% bu *% bx) >> 15) +% 128);
        v[i] = @truncate(((rv *% rx +% gv *% gx +% bv *% bx) >> 15) +% 128);
    }
}

pub fn rgbShuffle(d: [*]u8, dl: RgbLayout, s: [*]const u8, sl: RgbLayout, w: usize) void {
    if (simd.rgbShuffle(d, dl, s, sl, w)) return;
    for (0..w) |i| {
        const sp = s + i * sl.bpp;
        const dp = d + i * dl.bpp;
        dp[dl.r] = sp[sl.r];
        dp[dl.g] = sp[sl.g];
        dp[dl.b] = sp[sl.b];
        if (dl.bpp == 4) dp[dl.a] = if (sl.bpp == 4) sp[sl.a] else 255;
    }
}

pub fn grayToRgb(d: [*]u8, dl: RgbLayout, s: [*]const u8, w: usize) void {
    for (0..w) |i| {
        const dp = d + i * dl.bpp;
        dp[0] = s[i];
        dp[1] = s[i];
        dp[2] = s[i];
        if (dl.bpp == 4) dp[3] = 255;
    }
}

pub fn yuv2rgbTabRow(t: *const YuvTables, d: [*]u8, dl: RgbLayout, py: [*]const u8, pu: [*]const u8, pv: [*]const u8, w: usize) void {
    var i: usize = 0;
    if (simd.yuv2rgbTabRow(t, d, dl, py, pu, pv, w)) |done| i = done;
    while (i + 1 < w + 1 and i < w) : (i += 2) {
        const U = pu[i >> 1];
        const V = pv[i >> 1];
        const oR = t.offR[V];
        const oG = t.offGU[U] + t.offGV[V];
        const oB = t.offB[U];
        inline for (0..2) |q| {
            if (i + q < w) {
                const Y: i32 = py[i + q];
                const dp = d + (i + q) * dl.bpp;
                dp[dl.r] = t.ytab[@intCast(oR + Y)];
                dp[dl.g] = t.ytab[@intCast(oG + Y)];
                dp[dl.b] = t.ytab[@intCast(oB + Y)];
                if (dl.bpp == 4) dp[dl.a] = 255;
            }
        }
    }
}

// ---------------------------------------------------------------- input

pub fn rgbToY(t: *const Rgb2Yuv, dst: [*]i16, s: [*]const u8, l: RgbLayout, w: usize) void {
    if (simd.rgbToY(t, dst, s, l, w)) return;
    for (0..w) |i| {
        const p = s + i * l.bpp;
        const r: i32 = p[l.r];
        const g: i32 = p[l.g];
        const b: i32 = p[l.b];
        dst[i] = @truncate((t.ry * r + t.gy * g + t.by * b + (32 << 14) + (1 << 8)) >> 9);
    }
}

pub fn rgbaToA(dst: [*]i16, s: [*]const u8, l: RgbLayout, w: usize) void {
    for (0..w) |i| {
        const a: i16 = s[i * 4 + l.a];
        dst[i] = (a << 6) | (a >> 2);
    }
}

pub fn rgbToUV(t: *const Rgb2Yuv, du: [*]i16, dv: [*]i16, s: [*]const u8, l: RgbLayout, w: usize) void {
    if (simd.rgbToUV(t, du, dv, s, l, w)) return;
    for (0..w) |i| {
        const p = s + i * l.bpp;
        const r: i32 = p[l.r];
        const g: i32 = p[l.g];
        const b: i32 = p[l.b];
        du[i] = @truncate((t.ru * r + t.gu * g + t.bu * b + (256 << 14) + (1 << 8)) >> 9);
        dv[i] = @truncate((t.rv * r + t.gv * g + t.bv * b + (256 << 14) + (1 << 8)) >> 9);
    }
}

pub fn rgbToUVHalf(t: *const Rgb2Yuv, du: [*]i16, dv: [*]i16, s: [*]const u8, l: RgbLayout, w: usize) void {
    if (simd.rgbToUVHalf(t, du, dv, s, l, w)) return;
    for (0..w) |i| {
        const p = s + 2 * i * l.bpp;
        const q = p + l.bpp;
        const r: i32 = @as(i32, p[l.r]) + q[l.r];
        const g: i32 = @as(i32, p[l.g]) + q[l.g];
        const b: i32 = @as(i32, p[l.b]) + q[l.b];
        du[i] = @truncate((t.ru * r + t.gu * g + t.bu * b + (256 << 15) + (1 << 9)) >> 10);
        dv[i] = @truncate((t.rv * r + t.gv * g + t.bv * b + (256 << 15) + (1 << 9)) >> 10);
    }
}

// ---------------------------------------------------------------- horizontal

pub fn hscale8(dst: [*]i16, dw: usize, src: [*]const u8, f: *const filt.Filter) void {
    if (simd.hscale8(dst, dw, src, f)) return;
    const n = f.size;
    for (0..dw) |i| {
        const p: usize = @intCast(f.pos[i]);
        var val: i32 = 0;
        for (0..n) |j| val += @as(i32, src[p + j]) * f.coef[i * n + j];
        dst[i] = @intCast(@min(val >> 7, 32767));
    }
}

pub fn hscale16(dst: [*]i16, dw: usize, src: [*]const i16, f: *const filt.Filter) void {
    if (simd.hscale16(dst, dw, src, f)) return;
    const n = f.size;
    for (0..dw) |i| {
        const p: usize = @intCast(f.pos[i]);
        var val: i32 = 0;
        for (0..n) |j| val +%= @as(i32, @as(u16, @bitCast(src[p + j]))) *% f.coef[i * n + j];
        dst[i] = @intCast(@min(val >> 13, 32767));
    }
}

pub fn lumRange(r: Range, d: [*]i16, w: usize) void {
    switch (r) {
        .none => {},
        .to_jpeg => for (0..w) |i| {
            const v: i32 = @min(d[i], 30189);
            d[i] = @truncate((v * 19077 - 39057361) >> 14);
        },
        .from_jpeg => for (0..w) |i| {
            const v: i32 = d[i];
            d[i] = @truncate((v * 14071 + 33561947) >> 14);
        },
    }
}

pub fn chrRange(r: Range, u: [*]i16, v: [*]i16, w: usize) void {
    switch (r) {
        .none => {},
        .to_jpeg => for (0..w) |i| {
            const a: i32 = @min(u[i], 30775);
            const b: i32 = @min(v[i], 30775);
            u[i] = @truncate((a * 4663 - 9289992) >> 12);
            v[i] = @truncate((b * 4663 - 9289992) >> 12);
        },
        .from_jpeg => for (0..w) |i| {
            const a: i32 = u[i];
            const b: i32 = v[i];
            u[i] = @truncate((a * 1799 + 4081085) >> 11);
            v[i] = @truncate((b * 1799 + 4081085) >> 11);
        },
    }
}

// ---------------------------------------------------------------- vertical

pub fn vPlanar(d: [*]u8, w: usize, lines: []const [*]const i16, coef: []const i16) void {
    if (simd.vPlanar(d, w, lines, coef)) return;
    for (0..w) |i| {
        var val: i32 = 64 << 12;
        for (lines, coef) |l, cf| val +%= @as(i32, l[i]) * cf;
        d[i] = clip8(val >> 19);
    }
}

pub fn vInterleaved(d: [*]u8, w: usize, a: []const [*]const i16, b: []const [*]const i16, coef: []const i16) void {
    for (0..w) |i| {
        var u: i32 = 64 << 12;
        var v: i32 = 64 << 12;
        for (a, b, coef) |la, lb, cf| {
            u +%= @as(i32, la[i]) * cf;
            v +%= @as(i32, lb[i]) * cf;
        }
        d[2 * i] = clip8(u >> 19);
        d[2 * i + 1] = clip8(v >> 19);
    }
}

pub const PackedJob = struct {
    dst: [*]u8,
    w: usize,
    layout: RgbLayout,
    lum: []const [*]const i16,
    lcoef: []const i16,
    u: []const [*]const i16,
    v: []const [*]const i16,
    ccoef: []const i16,
    alpha: ?[]const [*]const i16,
};

fn isAlpha12(cf: []const i16) bool {
    if (cf.len != 2) return false;
    const a: u16 = @bitCast(cf[0]);
    const b: u16 = @bitCast(cf[1]);
    return @as(u32, a) + b == 4096 and b <= 4096;
}

inline fn writeFull(t: *const YuvTables, dp: [*]u8, l: RgbLayout, Yin: i32, U: i32, V: i32, A: i32, has_a: bool) void {
    var Y: i32 = Yin - t.y_off;
    Y *%= t.y_coeff;
    Y +%= 1 << 21;
    var R: i32 = Y +% V *% t.v2r;
    var G: i32 = Y +% V *% t.v2g +% U *% t.u2g;
    var B: i32 = Y +% U *% t.u2b;
    if (((R | G | B) & @as(i32, @bitCast(@as(u32, 0xC0000000)))) != 0) {
        R = std.math.clamp(R, 0, (1 << 30) - 1);
        G = std.math.clamp(G, 0, (1 << 30) - 1);
        B = std.math.clamp(B, 0, (1 << 30) - 1);
    }
    dp[l.r] = @intCast(R >> 22);
    dp[l.g] = @intCast(G >> 22);
    dp[l.b] = @intCast(B >> 22);
    if (l.bpp == 4) dp[l.a] = if (has_a) @intCast(A) else 255;
}

inline fn clipA(a: i32) i32 {
    return if (a & 0x100 != 0) std.math.clamp(a, 0, 255) else a;
}

pub fn packedFull(t: *const YuvTables, j: *const PackedJob) void {
    const l = j.layout;
    const has_a = j.alpha != null;
    if (j.lum.len == 1 and (j.ccoef.len == 1 or isAlpha12(j.ccoef))) {
        const uvalpha: i32 = if (j.ccoef.len == 1) 0 else j.ccoef[1];
        const b0 = j.lum[0];
        if (simd.packedFull1(t, j, uvalpha)) return;
        for (0..j.w) |i| {
            const Y: i32 = @as(i32, b0[i]) * 4;
            var U: i32 = undefined;
            var V: i32 = undefined;
            if (uvalpha < 2048) {
                U = (@as(i32, j.u[0][i]) - (128 << 7)) * 4;
                V = (@as(i32, j.v[0][i]) - (128 << 7)) * 4;
            } else {
                U = (@as(i32, j.u[0][i]) + j.u[1][i] - (128 << 8)) * 2;
                V = (@as(i32, j.v[0][i]) + j.v[1][i] - (128 << 8)) * 2;
            }
            var A: i32 = 0;
            if (has_a) A = clipA((@as(i32, j.alpha.?[0][i]) + 64) >> 7);
            writeFull(t, j.dst + i * l.bpp, l, Y, U, V, A, has_a);
        }
    } else if (j.lum.len == 2 and isAlpha12(j.lcoef) and isAlpha12(j.ccoef)) {
        const ya: i32 = j.lcoef[1];
        const ya1: i32 = 4096 - ya;
        const ua: i32 = j.ccoef[1];
        const ua1: i32 = 4096 - ua;
        if (simd.packedFull2(t, j, ya, ua)) return;
        for (0..j.w) |i| {
            const Y = (@as(i32, j.lum[0][i]) * ya1 + @as(i32, j.lum[1][i]) * ya) >> 10;
            const U = (@as(i32, j.u[0][i]) * ua1 + @as(i32, j.u[1][i]) * ua - (128 << 19)) >> 10;
            const V = (@as(i32, j.v[0][i]) * ua1 + @as(i32, j.v[1][i]) * ua - (128 << 19)) >> 10;
            var A: i32 = 0;
            if (has_a) A = clipA((@as(i32, j.alpha.?[0][i]) * ya1 + @as(i32, j.alpha.?[1][i]) * ya + (1 << 18)) >> 19);
            writeFull(t, j.dst + i * l.bpp, l, Y, U, V, A, has_a);
        }
    } else {
        if (simd.packedFullX(t, j)) return;
        for (0..j.w) |i| {
            var Y: i32 = 1 << 9;
            var U: i32 = (1 << 9) - (128 << 19);
            var V: i32 = (1 << 9) - (128 << 19);
            for (j.lum, j.lcoef) |ln, cf| Y +%= @as(i32, ln[i]) * cf;
            for (j.u, j.v, j.ccoef) |lu, lv, cf| {
                U +%= @as(i32, lu[i]) * cf;
                V +%= @as(i32, lv[i]) * cf;
            }
            Y >>= 10;
            U >>= 10;
            V >>= 10;
            var A: i32 = 0;
            if (has_a) {
                A = 1 << 18;
                for (j.alpha.?, j.lcoef) |ln, cf| A +%= @as(i32, ln[i]) * cf;
                A = clipA(A >> 19);
            }
            writeFull(t, j.dst + i * l.bpp, l, Y, U, V, A, has_a);
        }
    }
}

inline fn writeHalf(t: *const YuvTables, dp: [*]u8, l: RgbLayout, Y1: i32, Y2: i32, U: i32, V: i32, two: bool) void {
    const Uc: usize = @intCast(std.math.clamp(U, 0, 255));
    const Vc: usize = @intCast(std.math.clamp(V, 0, 255));
    const oR = t.offR[Vc];
    const oG = t.offGU[Uc] + t.offGV[Vc];
    const oB = t.offB[Uc];
    dp[l.r] = t.look(oR + Y1);
    dp[l.g] = t.look(oG + Y1);
    dp[l.b] = t.look(oB + Y1);
    if (l.bpp == 4) dp[l.a] = 255;
    if (two) {
        const q = dp + l.bpp;
        q[l.r] = t.look(oR + Y2);
        q[l.g] = t.look(oG + Y2);
        q[l.b] = t.look(oB + Y2);
        if (l.bpp == 4) q[l.a] = 255;
    }
}

pub fn packedHalf(t: *const YuvTables, j: *const PackedJob) void {
    const l = j.layout;
    const n = (j.w + 1) >> 1;
    if (j.lum.len == 1 and (j.ccoef.len == 1 or isAlpha12(j.ccoef))) {
        const uvalpha: i32 = if (j.ccoef.len == 1) 0 else j.ccoef[1];
        const b0 = j.lum[0];
        for (0..n) |i| {
            const Y1 = (@as(i32, b0[2 * i]) + 64) >> 7;
            const Y2 = (@as(i32, b0[2 * i + 1]) + 64) >> 7;
            var U: i32 = undefined;
            var V: i32 = undefined;
            if (uvalpha < 2048) {
                U = (@as(i32, j.u[0][i]) + 64) >> 7;
                V = (@as(i32, j.v[0][i]) + 64) >> 7;
            } else {
                U = (@as(i32, j.u[0][i]) + j.u[1][i] + 128) >> 8;
                V = (@as(i32, j.v[0][i]) + j.v[1][i] + 128) >> 8;
            }
            writeHalf(t, j.dst + 2 * i * l.bpp, l, Y1, Y2, U, V, 2 * i + 1 < j.w);
        }
    } else if (j.lum.len == 2 and isAlpha12(j.lcoef) and isAlpha12(j.ccoef)) {
        const ya: i32 = j.lcoef[1];
        const ya1: i32 = 4096 - ya;
        const ua: i32 = j.ccoef[1];
        const ua1: i32 = 4096 - ua;
        for (0..n) |i| {
            const Y1 = (@as(i32, j.lum[0][2 * i]) * ya1 + @as(i32, j.lum[1][2 * i]) * ya) >> 19;
            const Y2 = (@as(i32, j.lum[0][2 * i + 1]) * ya1 + @as(i32, j.lum[1][2 * i + 1]) * ya) >> 19;
            const U = (@as(i32, j.u[0][i]) * ua1 + @as(i32, j.u[1][i]) * ua) >> 19;
            const V = (@as(i32, j.v[0][i]) * ua1 + @as(i32, j.v[1][i]) * ua) >> 19;
            writeHalf(t, j.dst + 2 * i * l.bpp, l, Y1, Y2, U, V, 2 * i + 1 < j.w);
        }
    } else {
        if (simd.packedHalfX(t, j)) return;
        for (0..n) |i| {
            var Y1: i32 = 1 << 18;
            var Y2: i32 = 1 << 18;
            var U: i32 = 1 << 18;
            var V: i32 = 1 << 18;
            for (j.lum, j.lcoef) |ln, cf| {
                Y1 +%= @as(i32, ln[2 * i]) * cf;
                Y2 +%= @as(i32, ln[2 * i + 1]) * cf;
            }
            for (j.u, j.v, j.ccoef) |lu, lv, cf| {
                U +%= @as(i32, lu[i]) * cf;
                V +%= @as(i32, lv[i]) * cf;
            }
            writeHalf(t, j.dst + 2 * i * l.bpp, l, Y1 >> 19, Y2 >> 19, U >> 19, V >> 19, 2 * i + 1 < j.w);
        }
    }
}

