// Split 16 packed 24-bit pixels into three byte planes (memory order).
inline fn deint24(s: [*]const u8, c0: *@Vector(16, u8), c1: *@Vector(16, u8), c2: *@Vector(16, u8)) void {
    const m = comptime deint24Masks();
    const z: @Vector(16, u8) = @splat(0);
    const a: @Vector(16, u8) = s[0..16].*;
    const b: @Vector(16, u8) = s[16..32].*;
