    c2.* = @shuffle(u8, a, z, m[2][0]) | @shuffle(u8, b, z, m[2][1]) | @shuffle(u8, c, z, m[2][2]);
}

inline fn rgb24Planes(s: [*]const u8, l: k.RgbLayout, r: *V16s, g: *V16s, b: *V16s) void {
    var c0: @Vector(16, u8) = undefined;
