// Chroma lanes are stored as [c0..3 c8..11 | c4..7 c12..15] so that per-lane
// unpacklo/unpackhi yield pixels 0..15 / 16..31 in natural order.
inline fn ldChromaPerm(p: [*]const u8) V16u {
    const v: @Vector(16, u8) = p[0..16].*;
    const q = @shuffle(u8, v, undefined, [16]i32{ 0, 1, 2, 3, 8, 9, 10, 11, 4, 5, 6, 7, 12, 13, 14, 15 });
    return @as(V16u, q);
}
inline fn dupL(v: V16u) V16u {
    return @shuffle(u16, v, undefined, [16]i32{ 0, 0, 1, 1, 2, 2, 3, 3, 8, 8, 9, 9, 10, 10, 11, 11 });
}
inline fn dupH(v: V16u) V16u {
    return @shuffle(u16, v, undefined, [16]i32{ 4, 4, 5, 5, 6, 6, 7, 7, 12, 12, 13, 13, 14, 14, 15, 15 });
}

inline fn chroma32(t: *const k.YuvTables, pu: [*]const u8, pv: [*]const u8, cyr: V16u) Chroma32 {
    const U = ldChromaPerm(pu);
    const V = ldChromaPerm(pv);
    const oR = chromaOff(V, t.aR, t.cR);
    const oG = chromaOff(U, t.aGU + t.aGV, t.cGU) +% chromaOff(V, 0, t.cGV);
    const oB = chromaOff(U, t.aB, t.cB);
    var c: Chroma32 = undefined;
    chromaConst(oR, cyr, &c.rh, &c.rl);
    chromaConst(oG, cyr, &c.gh, &c.gl);
    chromaConst(oB, cyr, &c.bh, &c.bl);
    return c;
