inline fn chanEvalI(yhi: V16u, ylox: V16u, chi: V16u, clo: V16u) V16h {
    const sumx: V16h = @bitCast(ylox +% clo);
    const carry = sumx < @as(V16h, @bitCast(ylox));
    return @bitCast(yhi +% chi +% @select(u16, carry, @as(V16u, @splat(1)), @as(V16u, @splat(0))));
}

inline fn clampU8w(v: @Vector(32, i16)) @Vector(32, u8) {
    return @intCast(@min(@max(v, @as(@Vector(32, i16), @splat(0))), @as(@Vector(32, i16), @splat(255))));
}

fn rgb24LaneMasks(comptime swap: bool) [4][32]i32 {
    @setEvalBranchQuota(20000);
    // rg: per lane [R0..7, G0..7]; bb: per lane [B0..7, B0..7]
    // out A lane: output bytes 0..15 of the lane's 8 pixels, out B lane: bytes 16..23 (low 8)
    var m: [4][32]i32 = undefined;
