    m = re.match(r"^(0x[0-9a-f]+|\+\d+|-\d+|\*)\s+\S+\s+(\d+)", line)
    if m:
        a = m.group(1)
        if a.startswith("0x"): last = int(a, 16)
        elif a.startswith("+"): last += int(a[1:])
        elif a.startswith("-"): last -= int(a[1:])
        if "swscale_candidate" in names.get(cur, ""):
            counts[last] += int(m.group(2))
lines = {}
for l in open(dis):
    m = re.match(r"^\s+([0-9a-f]+):\s+(.*)", l)
    if m: lines[int(m.group(1), 16)] = m.group(2)
